var i=`0089-placinta-cu-branza`;var t=`world-0089`;var a=`MD`;var o=`eastern-europe`;var r=4;var s=79;var l={en:`Plăcintă cu Brânză`,ua:`Плацинда з бринзою`};var g={en:`A classic dish from Moldova, featuring chicken egg, bryndza, farmer cheese, dill. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Молдова. Основні складники: куряче яйце, бринза, домашній кисломолочний сир, кріп. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,500,`g`],[`water`,210,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,5,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`bryndza`,320,`g`],[`farmer-cheese`,220,`g`],[`dill`,15,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[[`unsalted-butter`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,120,`g`]]}];var u={slug:i,id:t,country:`MD`,region:o,servings:4,minutes:79,title:l,text:g,steps:d};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,i as slug,d as steps,g as text,l as title};